  /**
   * 10. クライアント側 行差分 (Unified Diff) 高速計算
   */
  public computeUnifiedDiff(oldCode: string, newCode: string): DiffResult {
    const oldLines = oldCode.split('\n');
    const newLines = newCode.split('\n');
    const resultLines: DiffLine[] = [];
    let additions = 0;
    let deletions = 0;
    let unchanged = 0;

    // 単純かつ高速なLCSベース差分近似
    let i = 0;
    let j = 0;

    while (i < oldLines.length || j < newLines.length) {
      if (i < oldLines.length && j < newLines.length && oldLines[i] === newLines[j]) {
        resultLines.push({
          type: 'unchanged',
          text: oldLines[i],
          oldLineNumber: i + 1,
          newLineNumber: j + 1,
        });
        unchanged++;
        i++;
        j++;
      } else {
        // 次に一致する箇所を探索
        let foundMatchInNew = -1;
        let foundMatchInOld = -1;

        for (let lookahead = 1; lookahead <= 5; lookahead++) {
          if (j + lookahead < newLines.length && oldLines[i] === newLines[j + lookahead]) {
            foundMatchInNew = j + lookahead;
            break;
          }
          if (i + lookahead < oldLines.length && oldLines[i + lookahead] === newLines[j]) {
            foundMatchInOld = i + lookahead;
            break;
          }
        }

        if (foundMatchInNew !== -1) {
          // newLines に追加された行
          while (j < foundMatchInNew) {
            resultLines.push({
              type: 'added',
              text: newLines[j],
              newLineNumber: j + 1,
            });
            additions++;
            j++;
          }
        } else if (foundMatchInOld !== -1) {
          // oldLines から削除された行
          while (i < foundMatchInOld) {
            resultLines.push({
              type: 'removed',
              text: oldLines[i],
              oldLineNumber: i + 1,
            });
            deletions++;
            i++;
          }
        } else {
          // 変更行 (古い行削除 + 新しい行追加)
          if (i < oldLines.length) {
            resultLines.push({
              type: 'removed',
              text: oldLines[i],
              oldLineNumber: i + 1,
            });
            deletions++;
            i++;
          }
          if (j < newLines.length) {
            resultLines.push({
              type: 'added',
              text: newLines[j],
              newLineNumber: j + 1,
            });
            additions++;
            j++;
          }
        }
      }
    }

    return { lines: resultLines, additions, deletions, unchanged };
  }

  /**
   * 11. リアルタイム構文検証 (ブラケット整合・JSON・基本構文チェック)
   */
  public checkCodeSyntax(code: string, fileName?: string): SyntaxCheckResult {
    if (!code || !code.trim()) {
      return { valid: true, error: null };
    }

    // JSON ファイルの場合
    if (fileName && fileName.endsWith('.json')) {
      try {
        JSON.parse(code);
        return { valid: true, error: null };
      } catch (err: any) {
        return { valid: false, error: err?.message || 'JSONパースエラー' };
      }
    }

    // カッコ・ブレース整合チェック
    const stack: { char: string; line: number }[] = [];
    const lines = code.split('\n');
    let inBlockComment = false;

    for (let lineIdx = 0; lineIdx < lines.length; lineIdx++) {
      const line = lines[lineIdx];
      let inString: string | null = null;
      let isEscaped = false;

      for (let charIdx = 0; charIdx < line.length; charIdx++) {
        const c = line[charIdx];
        const nextC = line[charIdx + 1];

        if (inBlockComment) {
          if (c === '*' && nextC === '/') {
            inBlockComment = false;
            charIdx++;
          }
          continue;
        }

        if (!inString && c === '/' && nextC === '*') {
          inBlockComment = true;
          charIdx++;
          continue;
        }

        if (!inString && c === '/' && nextC === '/') {
          // 行コメント終了
          break;
        }

        if (inString) {
          if (isEscaped) {
            isEscaped = false;
          } else if (c === '\\') {
            isEscaped = true;
          } else if (c === inString) {
            inString = null;
          }
          continue;
        }

        if (c === '"' || c === "'" || c === '`') {
          inString = c;
          continue;
        }

        if (c === '{' || c === '(' || c === '[') {
          stack.push({ char: c, line: lineIdx + 1 });
        } else if (c === '}' || c === ')' || c === ']') {
          if (stack.length === 0) {
            return {
              valid: false,
              error: `閉じカッコ '${c}' に対応する開きカッコがありません (行 ${lineIdx + 1})`,
              errorLine: lineIdx + 1,
            };
          }
          const last = stack.pop()!;
          const match =
            (last.char === '{' && c === '}') ||
            (last.char === '(' && c === ')') ||
            (last.char === '[' && c === ']');
          if (!match) {
            return {
              valid: false,
              error: `開きカッコ '${last.char}' (行 ${last.line}) に対し不正な閉じカッコ '${c}' が検出されました (行 ${lineIdx + 1})`,
              errorLine: lineIdx + 1,
            };
          }
        }
      }
    }

    if (stack.length > 0) {
      const unclosed = stack[stack.length - 1];
      return {
        valid: false,
        error: `開きカッコ '${unclosed.char}' (行 ${unclosed.line}) が閉じられていません`,
        errorLine: unclosed.line,
      };
    }

    return { valid: true, error: null };
  }

